#!/usr/bin/env Rscript
suppressPackageStartupMessages({library(ggplot2);library(patchwork);library(svglite);library(survival);library(scales)})
B <- "/data/y01014/diliyaer/BLCA_CAF_project/GDF15_CAF_project/analysis_revisions_20260906"; O <- "/data/y01014/diliyaer/BLCA_CAF_project/GDF15_CAF_project/final_analysis_20260907/Figure5_external_validation"; dir.create(O,recursive=TRUE,showWarnings=FALSE)
e1<-read.csv(file.path(B,"CCDC80_external_validation/GSE32894_CCDC80_immune_input.csv"));e2<-read.csv(file.path(B,"CCDC80_external_validation/GSE13507_CCDC80_immune_input.csv"));ec<-read.csv(file.path(B,"CCDC80_external_validation/CCDC80_external_immune_correlations.csv"));tc<-read.csv(file.path(B,"CCDC80_ECM_program_validation/TCGA_program_multivariable_input.csv"));tu<-read.csv(file.path(B,"CCDC80_ECM_program_validation/TCGA_program_univariable_Cox.csv"));im<-read.csv(file.path(B,"CCDC80_ECM_program_validation/IMvigor210_ECM_program_scores.csv"));iv<-read.csv(file.path(B,"CCDC80_ECM_program_validation/IMvigor210_ECM_program_validation.csv"));g1<-read.csv(file.path(B,"CCDC80_ECM_program_validation/GSE32894_ECM_program_scores.csv"));g2<-read.csv(file.path(B,"CCDC80_ECM_program_validation/GSE13507_ECM_program_scores.csv"))
P<-c(GSE32894="#356A8A",GSE13507="#C98245"); T<-theme_classic(base_family="Arial",base_size=8)+theme(plot.title=element_text(face="bold",size=9,hjust=0),plot.subtitle=element_text(size=6.5,colour="#444"),axis.title=element_text(size=8),axis.text=element_text(size=7),axis.line=element_line(linewidth=.45),axis.ticks=element_line(linewidth=.35),panel.grid.major=element_line(linewidth=.18,colour="#E9E9E9"),panel.grid.minor=element_blank(),legend.position="none",plot.margin=margin(5,6,5,6))
sc<-function(d,n,t)ggplot(d,aes(CCDC80_z,myeloid_score))+geom_point(size=1.5,alpha=.65,colour=P[n])+geom_smooth(method="lm",formula=y~x,se=TRUE,colour=P[n],fill=P[n],alpha=.15,linewidth=.55)+labs(title=t,subtitle=paste0(n,"; n = ",nrow(d)),x="CCDC80 expression (z)",y="Myeloid score")+T
pA<-sc(e1,"GSE32894","(A) Independent cohort");pB<-sc(e2,"GSE13507","(B) Independent cohort")
g1$cohort<-"GSE32894";g2$cohort<-"GSE13507";g3<-im[,c("sample_id","program_score")];g3$cohort<-"IMvigor210";dist<-rbind(g1,g2,g3);pA<-ggplot(dist,aes(cohort,program_score,fill=cohort))+geom_violin(trim=FALSE,alpha=.35,colour="#444",linewidth=.35)+geom_boxplot(width=.16,outlier.shape=NA,colour="#222",linewidth=.4)+geom_jitter(width=.08,size=.45,alpha=.35)+scale_fill_manual(values=c(GSE32894="#356A8A",GSE13507="#C98245",IMvigor210="#6D8E78"))+labs(title="(A) Program is measurable across cohorts",subtitle="CCDC80-associated ECM program score distributions",x=NULL,y="Program score")+T;pB<-sc(e1,"GSE32894","(B) CCDC80–myeloid association");pC<-sc(e2,"GSE13507","(C) CCDC80–myeloid association")
ec$metric<-factor(ec$variable,levels=c("CAF_score","myeloid_score","cytotoxicity","T_exhaustion"),labels=c("CAF score","Myeloid score","Cytotoxicity","T-cell exhaustion"));pD<-ggplot(ec,aes(cohort,metric,fill=rho))+geom_tile(colour="white",linewidth=.7)+geom_text(aes(label=sprintf("%.2f",rho)),size=2.5,colour="white",fontface="bold")+scale_fill_gradient2(low="#B8CBD4",mid="white",high="#356A8A",limits=c(0,.6))+labs(title="(D) Immune associations are reproducible",subtitle="Spearman ρ across independent bulk cohorts",x=NULL,y=NULL,fill="ρ")+T+theme(legend.position="right")
tc$group<-ifelse(tc$program_score>=median(tc$program_score),"High","Low");sf<-survfit(Surv(time,event)~group,data=tc);z<-summary(sf);km<-data.frame(time=z$time,surv=z$surv,strata=sub("group=","",z$strata));pE<-ggplot(km,aes(time,surv,colour=strata))+geom_step(linewidth=.7)+scale_colour_manual(values=c(High="#A34B45",Low="#356A8A"))+scale_y_continuous(labels=percent,limits=c(0,1))+labs(title="(E) TCGA bladder cancer survival",subtitle=paste0("Univariable HR = ",sprintf("%.2f",tu$HR),"; P = ",formatC(tu$p,format="f",digits=4)),x="Time (days)",y="Overall survival")+T
im2<-im[!is.na(im$immune_phenotype)&im$immune_phenotype!="",];pF<-ggplot(im2,aes(immune_phenotype,program_score,fill=immune_phenotype))+geom_boxplot(width=.58,outlier.shape=NA,alpha=.75)+geom_jitter(width=.12,size=.7,alpha=.45)+scale_fill_brewer(palette="Set2")+labs(title="(F) IMvigor210 immune phenotype",subtitle=paste0("P = ",formatC(iv$immune_p,format="f",digits=4)),x=NULL,y="CCDC80-associated ECM program")+T+theme(axis.text.x=element_text(angle=35,hjust=1))
fig<-(pA|pB)/(pC|pD)/(pE|pF)+plot_layout(heights=c(1,1,1));ggsave(file.path(O,"Figure5_external_validation.pdf"),fig,width=180,height=260,units="mm",device=cairo_pdf,bg="white");ggsave(file.path(O,"Figure5_external_validation.svg"),fig,width=180,height=260,units="mm",device=svglite,bg="white");ggsave(file.path(O,"Figure5_external_validation.tif"),fig,width=180,height=260,units="mm",dpi=600,compression="lzw",device="tiff",bg="white")
write.csv(e1,file.path(O,"Figure5_source_GSE32894.csv"),row.names=FALSE);write.csv(e2,file.path(O,"Figure5_source_GSE13507.csv"),row.names=FALSE);write.csv(ec,file.path(O,"Figure5_source_correlations.csv"),row.names=FALSE);write.csv(tc,file.path(O,"Figure5_source_TCGA_survival.csv"),row.names=FALSE);write.csv(im2,file.path(O,"Figure5_source_IMvigor210.csv"),row.names=FALSE)
